-- Catálogo del Convenio de Basilea: grupos, categorías Y, Listas A y B, características H, operaciones D/R y notas.
-- Fuente: texto oficial de la Secretaría del Convenio (ES/EN) + decisiones BC-14/12 y BC-15/18. Ver docs/FUENTES.md.

on conflict (code) do nothing;

on conflict (code) do update set list=excluded.list,annex=excluded.annex,group_code=excluded.group_code,description_es=excluded.description_es,description_en=excluded.description_en,hazardous=excluded.hazardous,status=excluded.status,effective_from=excluded.effective_from,effective_to=excluded.effective_to,related_codes=excluded.related_codes,source=coalesce(excluded.source,'Convenio de Basilea, texto oficial (Secretaría)'),note_es=excluded.note_es,verified=excluded.verified;

on conflict (h_code) do nothing;
on conflict (code) do nothing;
on conflict (annex,ord) do nothing;
