insert into public.basel_groups (code,annex,name_es,name_en) values
('Y-A','I','Corrientes de desechos','Waste streams'),
('Y-B','I','Desechos que tengan como constituyentes','Wastes having as constituents'),
('Y-II','II','Categorías de desechos que requieren una consideración especial','Categories of wastes requiring special consideration'),
('A1','VIII','DESECHOS METÁLICOS O QUE CONTENGAN METALES','METAL AND METAL-BEARING WASTES'),
('A2','VIII','DESECHOS QUE CONTENGAN PRINCIPALMENTE CONSTITUYENTES INORGÁNICOS, QUE PUEDAN CONTENER METALES O MATERIA ORGÁNICA','WASTES CONTAINING PRINCIPALLY INORGANIC CONSTITUENTS, WHICH MAY CONTAIN METALS AND ORGANIC MATERIALS'),
('A3','VIII','DESECHOS QUE CONTENGAN PRINCIPALMENTE CONSTITUYENTES ORGÁNICOS, QUE PUEDAN CONTENER METALES Y MATERIA INORGÁNICA','WASTES CONTAINING PRINCIPALLY ORGANIC CONSTITUENTS, WHICH MAY CONTAIN METALS AND INORGANIC MATERIALS'),
('A4','VIII','DESECHOS QUE PUEDEN CONTENER CONSTITUYENTES INORGÁNICOS U ORGÁNICOS','WASTES WHICH MAY CONTAIN EITHER INORGANIC OR ORGANIC CONSTITUENTS'),
('B1','IX','DESECHOS DE METALES Y DESECHOS QUE CONTENGAN METALES','METAL AND METAL-BEARING WASTES'),
('B2','IX','DESECHOS QUE CONTENGAN PRINCIPALMENTE CONSTITUYENTES INORGÁNICOS, QUE A SU VEZ PUEDAN CONTENER METALES Y MATERIALES ORGÁNICOS','WASTES CONTAINING PRINCIPALLY INORGANIC CONSTITUENTS, WHICH MAY CONTAIN METALS AND ORGANIC MATERIALS'),
('B3','IX','DESECHOS QUE CONTENGAN PRINCIPALMENTE CONSTITUYENTES ORGÁNICOS, QUE PUEDEN CONTENER METALES Y MATERIALES INORGÁNICOS','WASTES CONTAINING PRINCIPALLY ORGANIC CONSTITUENTS, WHICH MAY CONTAIN METALS AND INORGANIC MATERIALS'),
('B4','IX','DESECHOS QUE PUEDAN CONTENER COMPONENTES INORGÁNICOS U ORGÁNICOS','WASTES WHICH MAY CONTAIN EITHER INORGANIC OR ORGANIC CONSTITUENTS')
insert into public.basel_codes (code,list,annex,group_code,description_es,description_en,hazardous,status,effective_from,effective_to,related_codes,source,note_es,verified) values
('Y1','Y','I','Y-A','Desechos clínicos resultantes de la atención médica prestada en hospitales, centros médicos y clínicas','Clinical wastes from medical care in hospitals, medical centers and clinics',true,'vigente',null,null,null,null,null,true),
