('Y6','Y','I','Y-A','Desechos resultantes de la producción, la preparación y la utilización de disolventes orgánicos','Wastes from the production, formulation and use of organic solvents',true,'vigente',null,null,null,null,null,true),
('Y7','Y','I','Y-A','Desechos, que contengan cianuros, resultantes del tratamiento térmico y las operaciones de temple','Wastes from heat treatment and tempering operations containing cyanides',true,'vigente',null,null,null,null,null,true),
('Y8','Y','I','Y-A','Desechos de aceites minerales no aptos para el uso a que estaban destinados','Waste mineral oils unfit for their originally intended use',true,'vigente',null,null,null,null,null,true),
('Y9','Y','I','Y-A','Mezclas y emulsiones de desechos de aceite y agua o de hidrocarburos y agua','Waste oils/water, hydrocarbons/water mixtures, emulsions',true,'vigente',null,null,null,null,null,true),
('Y10','Y','I','Y-A','Sustancias y artículos de desecho que contengan, o estén contaminados por bifenilos policlorados (PCB), terfenilos policlorados (PCT) o bifenilos polibromados (PBB)','Waste substances and articles containing or contaminated with polychlorinated biphenyls (PCBs) and/or polychlorinated terphenyls (PCTs) and/or polybrominated biphenyls (PBBs)',true,'vigente',null,null,null,null,null,true),
('Y11','Y','I','Y-A','Residuos alquitranados resultantes de la refinación, destilación o cualquier otro tratamiento pirolítico','Waste tarry residues arising from refining, distillation and any pyrolytic treatment',true,'vigente',null,null,null,null,null,true),
('Y12','Y','I','Y-A','Desechos resultantes de la producción, preparación y utilización de tintas, colorantes, pigmentos, pinturas, lacas o barnices','Wastes from production, formulation and use of inks, dyes, pigments, paints, lacquers, varnish',true,'vigente',null,null,null,null,null,true),
('Y13','Y','I','Y-A','Desechos resultantes de la producción, preparación y utilización de resinas, látex, plastificantes o colas y adhesivos','Wastes from production, formulation and use of resins, latex, plasticizers, glues/adhesives',true,'vigente',null,null,null,null,null,true),
('Y14','Y','I','Y-A','Sustancias químicas de desecho, no identificadas o nuevas, resultantes de la investigación y el desarrollo o de las actividades de enseñanza y cuyos efectos en el ser humano o el medio ambiente no se conozcan','Waste chemical substances arising from research and development or teaching activities which are not identified and/or are new and whose effects on man and/or the environment are not known',true,'vigente',null,null,null,null,null,true),
('Y15','Y','I','Y-A','Desechos de carácter explosivo que no estén sometidos a una legislación diferente','Wastes of an explosive nature not subject to other legislation',true,'vigente',null,null,null,null,null,true),
('Y16','Y','I','Y-A','Desechos resultantes de la producción, preparación y utilización de productos químicos y materiales para fines fotográficos','Wastes from production, formulation and use of photographic chemicals and processing materials',true,'vigente',null,null,null,null,null,true),
('Y17','Y','I','Y-A','Desechos resultantes del tratamiento de superficie de metales y plásticos','Wastes resulting from surface treatment of metals and plastics',true,'vigente',null,null,null,null,null,true),
('Y18','Y','I','Y-A','Residuos resultantes de las operaciones de eliminación de desechos industriales','Residues arising from industrial waste disposal operations',true,'vigente',null,null,null,null,null,true),
('Y19','Y','I','Y-B','Metales carbonilos','Metal carbonyls',true,'vigente',null,null,null,null,null,true),
('Y20','Y','I','Y-B','Berilio, compuestos de berilio','Beryllium; beryllium compounds',true,'vigente',null,null,null,null,null,true),
('Y21','Y','I','Y-B','Compuestos de cromo hexavalente','Hexavalent chromium compounds',true,'vigente',null,null,null,null,null,true),
