('Y25','Y','I','Y-B','Selenio, compuestos de selenio','Selenium; selenium compounds',true,'vigente',null,null,null,null,null,true),
('Y26','Y','I','Y-B','Cadmio, compuestos de cadmio','Cadmium; cadmium compounds',true,'vigente',null,null,null,null,null,true),
('Y27','Y','I','Y-B','Antimonio, compuestos de antimonio','Antimony; antimony compounds',true,'vigente',null,null,null,null,null,true),
('Y28','Y','I','Y-B','Telurio, compuestos de telurio','Tellurium; tellurium compounds',true,'vigente',null,null,null,null,null,true),
('Y29','Y','I','Y-B','Mercurio, compuestos de mercurio','Mercury; mercury compounds',true,'vigente',null,null,null,null,null,true),
('Y30','Y','I','Y-B','Talio, compuestos de talio','Thallium; thallium compounds',true,'vigente',null,null,null,null,null,true),
('Y31','Y','I','Y-B','Plomo, compuestos de plomo','Lead; lead compounds',true,'vigente',null,null,null,null,null,true),
('Y32','Y','I','Y-B','Compuestos inorgánicos de flúor, con exclusión del fluoruro cálcico','Inorganic fluorine compounds excluding calcium fluoride',true,'vigente',null,null,null,null,null,true),
('Y33','Y','I','Y-B','Cianuros inorgánicos','Inorganic cyanides',true,'vigente',null,null,null,null,null,true),
('Y34','Y','I','Y-B','Soluciones ácidas o ácidos en forma sólida','Acidic solutions or acids in solid form',true,'vigente',null,null,null,null,null,true),
('Y35','Y','I','Y-B','Soluciones básicas o bases en forma sólida','Basic solutions or bases in solid form',true,'vigente',null,null,null,null,null,true),
('Y36','Y','I','Y-B','Asbesto (polvo y fibras)','Asbestos (dust and fibres)',true,'vigente',null,null,null,null,null,true),
('Y37','Y','I','Y-B','Compuestos orgánicos de fósforo','Organic phosphorus compounds',true,'vigente',null,null,null,null,null,true),
('Y38','Y','I','Y-B','Cianuros orgánicos','Organic cyanides',true,'vigente',null,null,null,null,null,true),
('Y39','Y','I','Y-B','Fenoles, compuestos fenólicos, con inclusión de clorofenoles','Phenols; phenol compounds including chlorophenols',true,'vigente',null,null,null,null,null,true),
('Y40','Y','I','Y-B','Éteres','Ethers',true,'vigente',null,null,null,null,null,true),
